// Inherit real native blast/damage tests, then add density-driven volley checks.
#define Generate_Mission_Starts Blast_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaignenemies.h"
static int Volley(BuildingClass* sam,TechnoClass* target){for(int i=0;i<Units.Count();++i)Units.Ptr(i)->IsDiscoveredByPlayer=true;for(int i=0;i<Infantry.Count();++i)Infantry.Ptr(i)->IsDiscoveredByPlayer=true;for(int i=0;i<Buildings.Count();++i)Buildings.Ptr(i)->IsDiscoveredByPlayer=true;int before=Bullets.Count();auto missile=static_cast<TechnoClass*>(sam)->Fire_At(target->As_Target(),0);Check("normal firing creates a base missile",missile!=nullptr);int count=Bullets.Count()-before;for(int i=Bullets.Count()-1;i>=0;--i){Check("all local salvo missiles have half-stock power",Bullets.Ptr(i)->Strength==25);delete Bullets.Ptr(i);}return count;}
static void Density(const std::string& dir,int enemies){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place density SAM",Put(sam,Center()));sam->PrimaryFacing=DIR_N;
 std::vector<UnitClass*> group;for(int i=0;i<enemies;++i){auto enemy=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place nearby hostile",Put(enemy,XY_Cell(Cell_X(Coord_Cell(sam->Coord))+2,Cell_Y(Coord_Cell(sam->Coord))+2)));Check("enemy fixture inside half-range circle",Distance(sam->Center_Coord(),enemy->Center_Coord())<=sam->Weapon_Range(0)/2);enemy->Strength=30000;group.push_back(enemy);}
 auto distant=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place distant target",Put(distant,XY_Cell(Cell_X(Coord_Cell(sam->Coord))+26,Cell_Y(Coord_Cell(sam->Coord)))));Check("distant enemy outside count",Distance(sam->Center_Coord(),distant->Center_Coord())>sam->Weapon_Range(0)/2);distant->Strength=30000;
 // Own, allied, neutral, dead and limbo actors must not inflate the count.
 for(auto house:{HOUSE_GOOD,HOUSE_JP,HOUSE_NEUTRAL}){if(house==HOUSE_JP){sam->House->Make_Ally(house);HouseClass::As_Pointer(house)->Make_Ally(HOUSE_GOOD);}auto f=new InfantryClass(INFANTRY_E1,house);Check("place excluded actor",Put(f,Coord_Cell(sam->Coord)));}
 auto dead=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place dead enemy fixture",Put(dead,Coord_Cell(sam->Coord)));dead->Strength=0;auto limbo=new UnitClass(UNIT_MTANK,HOUSE_BAD);(void)limbo;
 auto building=new BuildingClass(STRUCT_POWER,HOUSE_BAD);Check("place enemy building excluded from troop count",Put(building,Coord_Cell(sam->Coord)));
 int total=0;for(int i=0;i<2;++i){int before=int(sam->IsSecondShot);int n=Volley(sam,group.empty()?static_cast<TechnoClass*>(distant):group[0]);total+=n;Check("extra missiles preserve ordinary salvo phase",sam->IsSecondShot==(before==0));Check("extra missiles preserve normal rearm deadline",sam->Arm==sam->Rearm_Delay(before));}
 std::printf("DENSITY enemies=%d two_base_shots=%d expected=%d\n",enemies,total,2+enemies);Check("two normal shots add exactly enemy-count missiles",total==2+enemies);
 if(enemies==1){Campaign_SAM_Volley_Forget(sam);Check("fraction starts with one normal missile",Volley(sam,group[0])==1);int samId=Buildings.ID(sam),enemyId=Units.ID(group[0]);for(int i=0;i<Units.Count();++i)Campaign_Enemies_Mark_Extra(Units.Ptr(i));for(int i=0;i<Infantry.Count();++i)Campaign_Enemies_Mark_Extra(Infantry.Ptr(i));Check("save fractional volley credit",Save_Game((dir+"/fraction.sav").c_str(),"SAM FRACTION ONE HALF"));Check("reload fractional volley credit",Load_Game((dir+"/fraction.sav").c_str()));sam=Buildings.Ptr(samId);auto target=Units.Ptr(enemyId);int next=0;for(int i=0;i<1;++i)next+=Volley(sam,target);Check("saved half credit adds missile at next normal shot",next==2);
 Campaign_SAM_Volley_Forget(sam);Volley(sam,target);delete sam;auto replacement=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place replacement SAM",Put(replacement,Center()));int fresh=0;for(int i=0;i<1;++i)fresh+=Volley(replacement,target);std::printf("RECYCLED count=%d\n",fresh);Check("recycled building slot starts without stale credit",fresh==1);}
}
static void ScopeVolley(const std::string& dir){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_BAD);Check("place enemy SAM",Put(sam,Center()));auto target=new UnitClass(UNIT_MTANK,HOUSE_GOOD);Check("place enemy-SAM target",Put(target,Coord_Cell(sam->Coord)));int before=Bullets.Count();static_cast<TechnoClass*>(sam)->Fire_At(target->As_Target(),0);Check("enemy SAM keeps single stock missile",Bullets.Count()==before+1&&Bullets.Ptr(before)->Strength==50);}
static void MixedBoundary(const std::string& dir){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place mixed-density SAM",Put(sam,Center()));std::vector<FootClass*> enemies;
 for(int i=0;i<2;++i){auto tank=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place mixed hostile tank",Put(tank,Coord_Cell(sam->Coord)));enemies.push_back(tank);auto inf=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place mixed hostile infantry",Put(inf,Coord_Cell(sam->Coord)));enemies.push_back(inf);}
 auto extra=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place sixth mixed hostile",Put(extra,Coord_Cell(sam->Coord)));enemies.push_back(extra);auto air=new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD);air->Altitude=AircraftClass::FLIGHT_LEVEL;Check("place mixed hostile aircraft",Put(air,Coord_Cell(sam->Coord)));enemies.push_back(air);
 Check("vehicles infantry and aircraft all contribute to volley",Volley(sam,enemies[0])==4);
 auto actor=enemies.back();auto origin=actor->Coord;auto center=sam->Center_Coord();actor->Coord=XY_Coord(Coord_X(center)+sam->Weapon_Range(0)/2,Coord_Y(center));Campaign_SAM_Volley_Forget(sam);Check("enemy at exactly half the actual range is counted",Volley(sam,enemies[0])==4);
 actor->Coord=XY_Coord(Coord_X(center)+sam->Weapon_Range(0)/2+1,Coord_Y(center));std::printf("BOUNDARY requested=%d actual=%d\n",sam->Weapon_Range(0)/2+1,Distance(center,actor->Center_Coord()));Campaign_SAM_Volley_Forget(sam);Check("enemy beyond half-range radius is excluded",Volley(sam,enemies[0])==3);actor->Coord=origin;
 GameToPlay=GAME_SKIRMISH;int before=Bullets.Count();static_cast<TechnoClass*>(sam)->Fire_At(enemies[0]->As_Target(),0);Check("skirmish retains one stock missile",Bullets.Count()==before+1&&Bullets.Ptr(before)->Strength==50);GameToPlay=GAME_NORMAL;
}
static void LegacyCredit(const std::string& dir){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place legacy-credit SAM",Put(sam,Center()));auto enemy=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place legacy-credit enemy",Put(enemy,Coord_Cell(sam->Coord)));auto distant=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place separate legacy-credit volley target",Put(distant,XY_Cell(Cell_X(Coord_Cell(sam->Coord))+26,Cell_Y(Coord_Cell(sam->Coord)))));
 auto footer=[&](char version,unsigned char credit){CDFileClass file;char magic[8]={'C','N','C','S','A','M','0',version};std::vector<unsigned char> data(BUILDING_MAX,0);data[Buildings.ID(sam)]=credit;Check("open isolated footer fixture",file.Open((dir+"/legacy-footer.bin").c_str(),WRITE));file.Write(magic,8);file.Write(data.data(),data.size());file.Close();Check("read isolated footer fixture",file.Open((dir+"/legacy-footer.bin").c_str(),READ));bool result=Campaign_SAM_Volley_Load(file);file.Close();return result;};
 Check("old fifths footer accepted",footer('1',4));Check("old four-fifths becomes eight-tenths without losing credit",Volley(sam,enemy)==2);Check("old fractional remainder is preserved after extra missile",Volley(sam,enemy)==1);
 Check("invalid old fifths rejected",!footer('1',5));Check("invalid new tenths rejected",!footer('2',10));Check("new tenths footer accepted",footer('2',5));Check("saved half plus new half makes one extra missile",Volley(sam,enemy)==2);
}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Blast_Regression(directory);for(int count:{0,1,4,5,10,20})Density(dir,count);MixedBoundary(dir);LegacyCredit(dir);ScopeVolley(dir);std::printf("TOTAL DENSITY FAILURES %d\n",failures);return failures==0;}
